"""Fresh current-design timing and physical pin identity snapshot, no routed labels."""
import json,os,resource,shutil,subprocess,time
from pathlib import Path
from pre_route_endpoints import sha
R=Path(__file__).resolve().parents[1]
def read(p):return json.loads(p.read_text())
def main():
 build=R/'build/native_initial_timing_pin_snapshot_v3_2026-10-19';bp=build/'receipt.json';b=read(bp);binary=build/'sequence_vpr';assert sha(binary)==b['binary_sha256'];assert all(sha(p)==h for p,h in b['bindings'].items());buildprotocol=read(build/'protocol.json');assert all(sha(p)==h for p,h in buildprotocol['bindings'].items());placed=R/'experiments/prospective_external_family_development_place_v1_2026-10-19';end=R/'experiments/prospective_external_family_development_endpoints_v1_2026-10-19';vp=end/'independent_verification_v1.json';v=read(vp);assert v['connections']==15616 and all(sha(p)==h for p,h in v['bindings'].items());out=R/'experiments/prospective_external_family_current_initial_timing_v1_2026-10-19';out.mkdir(exist_ok=False);work=out/'work';work.mkdir();start=time.perf_counter();bindings={str(p):sha(p) for p in [bp,build/'protocol.json',binary,vp,end/'endpoints.json',end/'mapping_report.json',Path(__file__).resolve()]}
 for src,name in [(placed/'design.blif','design.blif'),(placed/'design.net','design.net'),(placed/'source.place','design.place')]:shutil.copyfile(src,work/name);assert sha(src)==sha(work/name);bindings.update({str(p):sha(p) for p in [src,work/name]})
 e=read(end/'endpoints.json');graph=Path(e['inputs']['graph']['path']);assert sha(graph)==e['graph_sha256'];arch=Path(read(placed/'protocol.json')['command'][1]);bindings.update({str(p):sha(p) for p in [graph,arch]});command=[str(binary),str(arch),'design.blif','--route','--net_file','design.net','--place_file','design.place','--route_file','must_not_be_generated.route','--read_rr_graph',str(graph),'--route_chan_width','128','--num_workers','1','--seed','1','--max_router_iterations','100','--check_route','full'];env={k:v for k,v in os.environ.items() if not k.startswith('ROUTECAST_')};sets={'ROUTECAST_INITIAL_CRITICALITY':str(work/'criticality.tsv'),'ROUTECAST_INITIAL_TIMING':str(work/'timing.tsv'),'ROUTECAST_INITIAL_PIN_MANIFEST':str(work/'pin_manifest.tsv')};env.update(sets);expected=sum(d['role']=='SINK' for d in read(end/'mapping_report.json')['pin_details']);assert expected==15970
 protocol=dict(command=command,environment_set=sets,bindings=bindings,expected_all_cluster_sink_pins=15970,expected_data_CIDs=15616,excluded_root_clock_pins=354,phase='Snapshot at first native criticality getter, exit before getter returns. Includes original REAL transformed criticality, atom metadata/bit aggregation and same-process physical pin identity.',scope='Fixed unknown-history development design only. No source/final routed timing, budget assignment, predictor promotion or strict family admission. No old design pin/CID map reused. All ROUTECAST env cleared except the3 observer paths.',AS_limit_bytes=8*2**30,timeout_seconds=None,staging_seconds=time.perf_counter()-start);(out/'protocol.json').write_text(json.dumps(protocol,indent=2));tick=time.perf_counter()
 def limit():resource.setrlimit(resource.RLIMIT_AS,(8*2**30,8*2**30));resource.setrlimit(resource.RLIMIT_CORE,(0,0))
 with (work/'native.log').open('x') as log:
  child=subprocess.Popen(command,cwd=work,env=env,stdout=log,stderr=subprocess.STDOUT,preexec_fn=limit);stat=Path(f'/proc/{child.pid}/stat').read_text().rsplit(') ',1)[1].split();(out/'live_process.json').write_text(json.dumps(dict(pid=child.pid,start_ticks=stat[19]),indent=2));print('EXTERNAL_INITIAL_TIMING_CHILD',child.pid,flush=True);code=child.wait()
 text=(work/'native.log').read_text();passed=code==0 and f'ROUTECAST INITIAL TIMING SNAPSHOT {expected} ' in text and f'ROUTECAST INITIAL PIN MANIFEST {expected} exit_before_first_getter_returns=1' in text and not list(work.glob('*.route'));assert all(sha(p)==h for p,h in bindings.items());files=[out/'protocol.json',work/'native.log',*[work/name for name in ['criticality.tsv','timing.tsv','pin_manifest.tsv'] if (work/name).exists()]];(out/'receipt.json').write_text(json.dumps(dict(status='CURRENT_DESIGN_PRESEARCH_TIMING_CAPTURED_PENDING_IDENTITY_BITS_AUDIT' if passed else 'CURRENT_DESIGN_TIMING_CAPTURE_FAILED_RETAINED',exit_code=code,capture_passed=passed,process_seconds=time.perf_counter()-tick,bindings={str(p):sha(p) for p in files},independent_verification_pending=True,new_route_labels=False),indent=2));print('EXTERNAL_INITIAL_TIMING_CAPTURE',passed,code,flush=True);assert passed
